style.css:
@-moz-document domain("youtube.com") {
body {
        background-image: url('https://images.alphacoders.com/670/670025.jpg');
        background-size: cover;
        background-position: center;
        color: white;
    }

    ytd-channel-header {
        position: relative;
    }

    ytd-channel-header::before {
        content: url('https://e7.pngegg.com/pngimages/444/325/png-clipart-blood-true-blood-miscellaneous-text.png');
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        z-index: 1;
    }

    #avatar img {
        position: relative;
        z-index: 2;
    }

    ytd-rich-grid-media:hover {
        box-shadow: 0 0 20px 5px rgba(255, 0, 0, 0.7);
    }

    ytd-rich-grid-media {
        box-shadow: 0 0 20px rgba(0, 0, 0, 0.6);
    }

    ytd-toggle-button-renderer,
    ytd-subscribe-button-renderer,
    ytd-video-secondary-info-renderer {
        position: relative;
    }

    ytd-toggle-button-renderer::after,
    ytd-subscribe-button-renderer::after,
    ytd-video-secondary-info-renderer::after {
        content: url('https://e7.pngegg.com/pngimages/574/949/png-clipart-bloodstain-pattern-analysis-pillow-splatter-film-blood-splatter-lip-dexter.png');
        position: absolute;
        bottom: -20px;
        left: 50%;
        transform: translateX(-50%);
        width: 30px;
        height: 30px;
        z-index: 1;
    }

    ytd-toggle-button-renderer,
    ytd-subscribe-button-renderer {
        background-color: #8B0000;
    }
}
